const state = items[0]?.json?.state || items[0]?.json || {};
const targets = state.inputs?.delivery_targets || ['webhook_response'];
state.delivery = state.delivery || {};
state.delivery.targets = targets;
state.delivery.final_artifact_type = 'presentation_prompt';
state.delivery.payloads = {
  presentation_tool: {
    action: 'copy_prompt_into_gamma_canva_or_ppt',
    artifact_field: 'presentation_prompt.prompt_text',
    note: 'Paste the executive presentation prompt into Gamma, Canva, PowerPoint Copilot, or similar.',
  },
  full_report: {
    action: 'copy_full_report_markdown',
    artifact_field: 'final_report_markdown',
  },
};
state.audit_log = state.audit_log || [];
state.audit_log.push({ timestamp: new Date().toISOString(), workflow_name: 'WF_DELIVERY', status: 'OK', message: 'Delivery payloads prepared for report and presentation prompt.' });
return [{ json: state }];

const state = items[0]?.json?.state || items[0]?.json || {};
const targets = state.inputs?.delivery_targets || ['webhook_response'];
state.delivery = state.delivery || {};
state.delivery.targets = targets;
state.delivery.final_artifact_type = 'gamma_deck_outline';
state.delivery.gamma_api_enabled = Boolean(state.inputs?.gamma_api_enabled);
state.delivery.gamma_api_status = state.delivery.gamma_api_enabled ? 'ready_when_gamma_credentials_are_configured' : 'disabled_manual_gamma_markdown_fallback';
state.delivery.payloads = {
  gamma_ai: {
    action: state.delivery.gamma_api_enabled ? 'future_direct_gamma_api_create_deck' : 'copy_or_import_to_gamma',
    artifact_field: 'gamma_deck.gamma_markdown',
    slides_field: 'gamma_deck.slides_json',
    gamma_api_node: 'Future Gamma API Create Deck (Disabled)',
    gamma_api_status: state.delivery.gamma_api_status,
    note: state.delivery.gamma_api_enabled ? 'Enable the disabled Gamma HTTP node and attach founder credentials when the Gamma API key is available.' : 'Gamma API is not required. Founder can paste/import this outline into Gamma AI.'
  },
  google_docs: targets.includes('google_docs') ? { action: 'create_document_optional', markdown_field: 'gamma_deck.gamma_markdown', share_with: 'founder' } : null,
  pdf: targets.includes('pdf') ? { action: 'optional_pdf_from_gamma_outline', provider: 'configured_pdf_api_if_needed' } : null,
  slack: targets.includes('slack') ? { action: 'post_gamma_outline_or_link', channel: 'configured_review_or_delivery_channel' } : null,
  webhook_response: { action: 'return_json', fields: ['run_id','gamma_deck','entity','normalized.source_coverage','delivery'] }
};
state.delivery.status = state.gamma_deck?.status === 'ready' ? 'gamma_delivery_payload_prepared' : 'gamma_deck_missing';
state.audit_log = state.audit_log || [];
state.audit_log.push({ timestamp: new Date().toISOString(), workflow_name: 'WF_DELIVER', status: state.delivery.status === 'gamma_delivery_payload_prepared' ? 'READY' : 'WARN', message: `Delivery payload prepared. Gamma API branch is ${state.delivery.gamma_api_status}.` });
return [{ json: state }];
